// Cross-implementation test vectors for the NEAR contract `contracts/season-commit`.
// Seasons are generated by the real v2 engine (with deterministic "random" bytes so the
// output is reproducible); leaves, roots and paths come from crypto.js. The Rust unit and
// sandbox tests consume the JSON and must reproduce every hash byte for byte.
// Usage: npm run vectors   (writes contracts/season-commit/tests/vectors.json)
import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import * as E from '../src/game/engine.js';
import { sha256, merkle, proofFor, verifyProof } from '../src/game/crypto.js';

export const OUT = fileURLToPath(new URL('../../contracts/season-commit/tests/vectors.json', import.meta.url));
const SCHEMA = 'v2';
const SEEDS = [101, 202, 303];
// English test phrases for Ash's key (the contract treats a phrase as opaque UTF-8;
// the last one has multi-byte characters on purpose).
const ASH_PHRASES = ['water remembers stone', 'we arrived before our time', 'silence is also an answer \u2014 na\u00efve \u221e'];

/** Deterministic byte source: SHA-256 in counter mode. Only for vectors, never for play. */
function detBytes(tag) {
  let counter = 0;
  const pool = [];
  return (n) => {
    const out = new Uint8Array(n);
    for (let i = 0; i < n; i++) {
      if (!pool.length) {
        const h = sha256(`ftf-vectors|${tag}|${counter++}`);
        for (let j = 0; j < 64; j += 2) pool.push(parseInt(h.slice(j, j + 2), 16));
      }
      out[i] = pool.shift();
    }
    return out;
  };
}

/** The canonical event bytes exactly as engine.js leafHash() serializes them. */
const canonicalEvent = (e) => JSON.stringify({ t: e.t, place: e.place, action: e.action, power: e.power, delay: e.delay, dots: e.dots });
const leafOf = (seasonId, index, body, salt) => sha256(`ftf:leaf:${SCHEMA}|${seasonId}|${index}|${body}|${salt}`);
const hexOf = (bytes) => Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');

function season(seed, k) {
  const S = E.newSeason(seed, { rules: 'v2', randomBytes: detBytes(`season-${seed}`) });
  const leaves = S.events.map((e, index) => {
    const body = canonicalEvent(e);
    // Guard: the formula above must be the engine's own leaf, or the vectors are worthless.
    if (leafOf(S.seasonId, index, body, e.salt) !== e.leaf) throw new Error(`leaf formula drifted from engine.js (seed ${seed}, index ${index})`);
    const path = proofFor(S.levels, index);
    if (!verifyProof(e.leaf, path, S.root)) throw new Error('crypto.js proof does not verify');
    return { index, canonicalEvent: body, salt: e.salt, leaf: e.leaf, path };
  });
  if (E.keyCommit(S.pepelKey.phrase, S.pepelKey.salt) !== S.pepelKey.hash) throw new Error('keyCommit drifted');
  const phrase = ASH_PHRASES[k];
  const ashKey = { phrase, salt: S.pepelKey.salt, commitment: E.keyCommit(phrase, S.pepelKey.salt) };
  if (ashKey.commitment !== sha256(`ftf:key:${SCHEMA}|${S.seasonId}|${phrase}|${ashKey.salt}`)) throw new Error('key formula drifted from engine.js');
  return { seed, seasonId: S.seasonId, schemaVersion: SCHEMA, scheduleRoot: S.root, leafCount: leaves.length, leaves, ashKey };
}

/** Small trees (1, 2, 5 leaves) built with the same leaf formula, for shapes the engine never produces. */
function edgeTree(n) {
  const rb = detBytes(`edge-${n}`);
  const seasonId = hexOf(rb(8));
  const events = Array.from({ length: n }, (_, i) => ({ t: 3 + i, place: i % 4, action: (i + 1) % 4, power: (i + 2) % 4, delay: 1 + (i % 2), dots: (i + 3) % 4 }));
  const items = events.map((e, index) => {
    const salt = hexOf(rb(32));
    const body = canonicalEvent(e);
    return { index, canonicalEvent: body, salt, leaf: leafOf(seasonId, index, body, salt) };
  });
  const levels = merkle(items.map((x) => x.leaf));
  const root = levels[levels.length - 1][0];
  const leaves = items.map((x) => {
    const path = proofFor(levels, x.index);
    if (!verifyProof(x.leaf, path, root)) throw new Error('edge proof does not verify');
    return { ...x, path };
  });
  return { seed: null, seasonId, schemaVersion: SCHEMA, scheduleRoot: root, leafCount: n, leaves, ashKey: null };
}

export function buildVectors() {
  return {
    about: 'Generated by game/scripts/gen-contract-vectors.mjs from engine.js (rules v2) and crypto.js. Do not edit by hand.',
    schemaVersion: SCHEMA,
    leafPreimage: 'ftf:leaf:<schemaVersion>|<seasonId>|<index>|<canonicalEvent>|<salt>',
    nodePreimage: '<leftHex><rightHex> (64+64 lowercase hex characters); a missing right node duplicates the left one',
    keyPreimage: 'ftf:key:<schemaVersion>|<seasonId>|<phrase>|<salt>',
    seasons: SEEDS.map(season),
    edgeTrees: [1, 2, 5].map(edgeTree),
  };
}

export const serialize = (v) => JSON.stringify(v, null, 1) + '\n';

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const v = buildVectors();
  writeFileSync(OUT, serialize(v));
  console.log(`wrote ${OUT}: ${v.seasons.length} seasons, ${v.edgeTrees.length} edge trees`);
}